def find_permutation(n, p):
    # Create a list to store the result permutation q
    q = [-1] * n

    # Create a list to keep track of which elements have been used
    used = [False] * n

    def backtrack(i):
        if i == n:
            return True
        for j in range(n):
            if not used[j] and (q[j] == -1 or q[q[j]] == p[i]):
                q[j] = i + 1
                used[j] = True
                if backtrack(i + 1):
                    return True
                q[j] = -1
                used[j] = False
        return False

    if backtrack(0):
        return q
    else:
        return [-1]

